commands.command:
set -eu
[ -z "$(git status --short)" ]
cat > main/gateway_link.h <<'EOF'
#pragma once

#include <stdint.h>

#include "esp_err.h"
#include "gateway_events.h"

esp_err_t gateway_link_start(void);
void gateway_link_publish_event(const gateway_event_t *event);
uint32_t gateway_link_take_dropped(void);
EOF
cat > main/gateway_link.c <<'EOF'
#include "gateway_link.h"

#include "gateway_uart_link.h"

esp_err_t gateway_link_start(void)
{
    return gateway_uart_link_start();
}

void gateway_link_publish_event(const gateway_event_t *event)
{
    gateway_uart_link_publish_event(event);
}

uint32_t gateway_link_take_dropped(void)
{
    return gateway_uart_link_take_dropped();
}
EOF
python3 - <<'PY'
from pathlib import Path

def replace(path, old, new):
    p = Path(path)
    text = p.read_text()
    if old not in text:
        raise SystemExit(f'missing expected text in {path}: {old!r}')
    p.write_text(text.replace(old, new))

replace('main/app_main.c', '#include "gateway_uart_link.h"', '#include "gateway_link.h"')
replace('main/app_main.c', 'ESP_ERROR_CHECK(gateway_uart_link_start());', 'ESP_ERROR_CHECK(gateway_link_start());')
replace('main/gateway_transport.c', '#include "gateway_uart_link.h"', '#include "gateway_link.h"')
replace('main/gateway_transport.c', 'gateway_uart_link_publish_event(&event);', 'gateway_link_publish_event(&event);')
replace('main/gateway_transport.c', 'gateway_uart_link_take_dropped()', 'gateway_link_take_dropped()')
replace('main/CMakeLists.txt', '        "gateway_inputs.c"\n        "gateway_link_protocol.c"', '        "gateway_inputs.c"\n        "gateway_link.c"\n        "gateway_link_protocol.c"')
PY
git diff --check
git status --short
git diff -- main/CMakeLists.txt main/app_main.c main/gateway_transport.c main/gateway_link.c main/gateway_link.h

